"""Generate every reported numeric table from retained experiment evidence."""
import json
import platform
from pathlib import Path
from project_b.detectors import PROBLEMS

ROOT=Path(__file__).parent


def read(path):return json.loads((ROOT/path).read_text())
def pct(x):return f'{100*x:.2f}%'
def write(name,lines): (ROOT/name).write_text('\n'.join(lines)+'\n')


def generate():
    a,b=read('results/benchmark_a.json'),read('results/benchmark_b.json')
    live=read('results/live/summary.json') if (ROOT/'results/live/summary.json').exists() else None
    official=a['official_validation']
    lines=['# Project A results','', '**Status: offline evidence complete for implemented deterministic paths; assignment submission gates remain open.**','',
           'Expected outputs come from a separately coded piecewise-formula oracle, not the official calculator. Agreement is regression evidence, not independent legal certification.','',
           '| Implementation | Correct / evaluated outputs | Exact accuracy | Median ms | p95 ms | Paid API USD / 1,000 |',
           '|---|---:|---:|---:|---:|---:|']
    for x in a['measurements']:
        lines.append(f"| {x['implementation']} | {x['correct_outputs']} / {x['evaluated_outputs']} | {pct(x['accuracy'])} | {x['median_ms']:.4f} | {x['p95_ms']:.4f} | 0; compute excluded |")
    if live and live.get('tax'):
        tax=live['tax'];correct=sum(x.get('correct',False) for x in tax)
        lat=sorted(x['seconds']*1000 for x in tax)
        lines.append(f"| Gemini at query time ({live['model']}) | {correct} / {len(tax)} | {pct(correct/len(tax))} | {lat[len(lat)//2]:.2f} | {lat[int(.95*(len(lat)-1))]:.2f} | See usage log; configured pricing required |")
    else:
        lines.append('| Gemini at query time | NOT RUN | unavailable | unavailable | unavailable | unavailable |')
    lines += ['',f"Each deterministic implementation evaluated {a['measurements'][0]['taxpayer_cases']} taxpayer cases under both regimes, spanning both FYs, ages, residency, slab/rebate/surcharge boundaries, deduction caps and rounding neighbours.",
              'Compiled rules were generated by Codex and run by a constrained interpreter. Gemini compilation has a runnable candidate path but is not silently substituted for that provenance. See evidence/COMPILATION_PROVENANCE.md.','',
              '## Repetition, explanation and input handling','',
              '| Implementation | Inputs repeated | Repeats per input | Inputs with varying output | Outputs with clause labels |',
              '|---|---:|---:|---:|---:|']
    for x in a['measurements']:
        lines.append(f"| {x['implementation']} | {x['repetition_inputs']} | {x['repetitions_per_input']} | {x['differing_inputs']} | {x['trace_nonempty_clause_outputs']} |")
    lines += ['', 'Repetitions execute the engine ten times without answer caching. Clause-label coverage does not prove legal correctness; reviewer inspection is required. Traces expose deductions, taxable-income rounding, slab tax, rebate, marginal relief, surcharge, cess and final rounding.',
              f"The conservative rule parser matched the expected ready/clarification status in {a['parser']['correct_status']} / {a['parser']['cases']} curated descriptions, including Hinglish and contradictions. This is a small hand-curated test set. Gemini extraction accuracy is {'in results/live/summary.json' if live else 'NOT RUN'}. A safe clarification is counted as correct only where the fixture expects one.",
              'Structured API amounts are annual eligible INR amounts. Zero defaults are explicit API conventions. Free text cannot use them until the user confirms omitted claims are zero. HRA requires a consistent rented period; changing periods require clarification/manual breakdown.',
              '', '## Official calculator evidence','',
              f"Verified cases in BOTH regimes: **{official['distinct_cases_both_regimes']} / {official['required_cases_both_regimes']}**. Verified individual regime checks: {official['verified_regime_checks']}. Mismatches: {len(official['mismatches'])}; invalid evidence entries: {len(official['invalid_evidence'])}.",
              'The 30-case register is project_a/fixtures/official_checks.csv. Pending rows are not passed checks. The independent oracle and this register must not be conflated. The calculator also excludes tax credits and unsupported income/deductions; it returns annual liability, not a refund/TDS balance.',
              '', '## Task 5: stale-law simulation, not a timed human migration','',
              '| Implementation | FY 2025-26 outputs tested | Silent errors if routed through stale FY | Errors after current FY routing | Regression seconds | Human change time |',
              '|---|---:|---:|---:|---:|---|']
    for x in a['law_change_simulation']:
        lines.append(f"| {x['implementation']} | {x['evaluated_outputs']} | {x['stale_year_silent_wrong_answers']} | {x['updated_wrong_answers']} | {x['regression_seconds']:.4f} | NOT RECORDED |")
    lines += ['', 'Both FY implementations were built in this session. These timings measure the regression exercise only, not authoring or legal review. Routing a new-year request to old-year rules returns plausible but wrong answers without an exception. The normal compiled loader rejects a mismatched FY/configuration. New-regime slabs and rebate change; old-regime and other scoped deductions stay pinned. Query-time Gemini law-change evidence remains pending live execution.',
              '', '## Final design for 100,000 users (provisional; under two pages)','',
              '**Input extraction: hybrid.** Validate structured fields with deterministic types and ranges. Use Gemini for flexible language extraction only after that path has been measured. Missing, contradictory or unsupported information returns clarifying questions; no liability is produced until resolved. Cache static rule text, not private user descriptions.',
              '**Tax arithmetic and recommendation: rules.** The two deterministic paths agree on the frozen suite and are repeatable in this experiment. An LLM does not earn a per-request arithmetic role on the present evidence. Compare both computed liabilities; report a tie rather than fabricating a preference. Use decimals and statutory rounding.',
              '**Legal updates: hybrid authoring, deterministic execution.** An LLM may propose declarative changes. A reviewer compares official clauses, inspects a typed diff, adds independent boundary cases, checks the official calculator and signs the release. Candidates cannot auto-promote. Pin FY plus rule hash in the response and retain the arithmetic trace. Roll back a release without changing historic rule versions.',
              '**Operations: rules and human release controls.** Deploy a stateless service with authenticated access, input-size limits, no taxpayer text in routine logs, and traces tied to request IDs. 100,000 users is not an RPS specification; load-test the expected peak concurrency, measure parser quotas and use a queue/circuit breaker for Gemini. Missing extraction service should return a structured form, not a guessed answer.',
              '**Next Budget:** keep old rules immutable, ingest only named official provisions, add threshold tests before promotion, run both old and candidate rules in shadow mode, then release the new FY after calculator validation. This is not yet a production tax service: official verification, legal review, Gemini evidence, peak-load tests and the requested contemporaneous migration record remain outstanding.']
    write('RESULTS_A.md',lines)

    profile=read('results/profile_b.json')
    lines=['# Project B results','', '**Status: real-data profile, injector, rule/statistical detectors and offline hybrid measured. Gemini family remains unmeasured unless live evidence is present.**','',
           f"Source sample: {b['sample_rows']:,} NYC 311 requests created in 2023, first ordered monthly quotas. This is not a probability sample or a full-year census. Source queries and SHA-256 are in data/nyc311_2023.manifest.json.",
           f"Train/validation/test: {b['split']['train']:,} / {b['split']['validation']:,} / {b['split']['test']:,}, split by stable hash of unique request key. Structurally screened validation/test pools: {b['split']['validation_structurally_valid']:,} / {b['split']['test_structurally_valid']:,}. Training frequencies are never fitted on injected evaluation data.",
           '', '## Existing raw-data findings','', '| Finding | Count | Interpretation |','|---|---:|---|']
    for key,val in profile['rule_flags'].items():
        description={'reversed_dates':'Closure precedes creation; inspect agency corrections/time semantics',
                     'near_duplicates':'Similarity candidates; repeated legitimate complaints can look alike',
                     'resolution_status':'Lexical contradiction candidates; resolution text may describe an earlier workflow stage',
                     'personal_data':'Pattern matches, not adjudicated PII; names and ordinary phrases can collide'}.get(key,'Rule flags requiring review')
        lines.append(f"| {key} | {val['count']} | {description} |")
    lines += ['', 'Counts and redacted row examples are in results/profile_b.json. Missing optional data is a profile characteristic, not automatically a defect.','',
              '| Column | Missing/empty |','|---|---:|']
    for key,count in profile['missing_counts'].items(): lines.append(f'| {key} | {count} |')
    lines += ['', '## Controlled evaluation','',
              'Each problem has three held-out seeds and 1%, 5%, 15% requested corruption rates. Injected row IDs are stored separately from detector inputs. Duplicates append rows; their realized final fraction differs slightly. Schema rename/drop affects the whole batch, so row-rate control is inapplicable. Agency null spikes affect one agency. Both schema rename and drop occur across seeds.',
              '**False-alarm caveat:** the uncorrupted holdout is structurally screened, not independently annotated for semantic correctness. The reported clean-row/batch flag rates are proxy FPR, not verified false-alarm rates. Real residual anomalies can be counted as apparent false alarms. Broad semantic validity needs human adjudication.',
              'Throughput is measured on the execution host, not the applicant laptop. USD figures below are paid API charges only and exclude CPU/storage/operations. LLM NOT RUN is unavailable, never zero.','',
              '| Problem | Family | Injected-row detection | Clean proxy row flags | Clean proxy batch flags | Corrupt batch detection | Rows/sec | Paid API USD/million rows |',
              '|---|---|---:|---:|---:|---:|---:|---|']
    live_b={x['problem']:x for x in (live or {}).get('b',[])}
    for problem in PROBLEMS:
        for family in ['rule','statistical']:
            x=next(x for x in b['measurements'] if x['problem']==problem and x['family']==family)
            lines.append(f"| {problem} | {family} | {pct(x['detection_rate'])} | {pct(x['clean_proxy_row_flag_rate'])} | {pct(x['clean_proxy_batch_flag_rate'])} | {pct(x['corrupt_batch_detection_rate'])} | {x['rows_per_second']:.0f} | 0; compute excluded |")
        x=live_b.get(problem)
        if x and x.get('ok'):
            lines.append(f"| {problem} | Gemini (smaller live scope) | {pct(x['tp']/max(1,x['tp']+x['fn']))} | {'unavailable' if x.get('clean_proxy_flagged') is None else pct(x['clean_proxy_flagged']/x['clean_n'])} | see raw evidence | see raw evidence | {x['metadata']['rows']/x['seconds']:.0f} | token pricing required |")
        else: lines.append(f'| {problem} | Gemini | NOT RUN | unavailable | unavailable | unavailable | unavailable | unavailable |')
    lines += ['', 'Every implemented alert includes a reason; wording presence is measured, but explanation usefulness has not been human-scored. Statistical schema/type/date novelty overlaps with declarative contracts and is intentionally a weak baseline. No sophisticated ML performance is claimed.',
              'Near-duplicates use bounded blocking (last 50 candidates); cross-block/cross-chunk matches may be missed. ZIP/borough and complaint/descriptor checks use observed source associations, not external authoritative mappings. PII rules cover formatted phone/email and cue-based names, not all names or personal data.',
              '', '## Hybrid selected on validation, evaluated on held-out test','',
              'Selection score = injected-row recall minus clean-proxy row flag rate; prefer rules on ties. LLM is excluded from winner selection until measured. The choices are provisional for these corruption templates.','',
              '| Problem | Selected offline family | Held-out detection | Clean proxy row flags |','|---|---|---:|---:|']
    for x in b['hybrid_measurements']:
        lines.append(f"| {x['problem']} | {b['choices'][x['problem']]} | {pct(x['detection_rate'])} | {pct(x['clean_proxy_row_flag_rate'])} |")
    e=b['end_to_end']
    lines += ['',f"Joint-corruption end-to-end run: {e['rows']:,} rows in {e['seconds']:.4f} seconds ({e['rows_per_second']:.0f} rows/sec), {e['llm_calls']} LLM calls, USD {e['paid_api_usd']} paid API cost. Per-problem alert counts are in benchmark_b.json. Joint corruptions can overwrite earlier ones, so this stress run does not claim combined ground-truth recall.",
              'Optional Gemini escalation reviews capped semantic candidates and reserves 20% of its row budget for otherwise unflagged sampling. It preserves deterministic hard-error alerts. Candidate backlog and unreviewed rows are explicit. This optional stage has not earned production selection on offline evidence.',
              '', '## Scale design: 50 million rows/day across 120 customers (under two pages)','',
              f"Assume 50 million rows/day is the **aggregate** across tenants, uniformly arriving: {50000000/86400:.1f} rows/sec on average and {50000000/120:,.0f} rows/customer/day if equally sized. Real tenant skew and bursts invalidate the equal-share assumption. At this sample's measured full-pipeline rate, a linear single-process extrapolation is {50000000/e['rows_per_second']/3600:.2f} process wall-hours/day. This is a rough lower-bound planning estimate, not a load test; schema diversity, I/O, memory pressure, dedup state and traffic bursts are absent.",
              '**Rules on ingestion.** Keep per-customer versioned schemas and explicit timestamp/coordinate contracts. Quarantine schema changes; never coerce silently. Partition by tenant/date/agency. Maintain idempotency keys and bounded indexed dedup windows so duplicates crossing batch boundaries are caught. Near-duplicate blocking needs recall audits and distributed state rather than a single in-memory sample.',
              '**Statistics per window.** Retain tenant-and-agency baselines with minimum sample sizes, seasonality windows and approved updates. Use labelled alert review to tune thresholds; apply alert grouping and false-discovery controls across 120 schemas. Novel categories become review candidates, not automatic invalid data. Do not train baselines on quarantined corruptions.',
              '**Bound LLM work.** If fraction f is reviewed and measured mean tokens/row is t, daily review tokens are 50,000,000*f*t. At f=0.001 there are 50,000 reviewed rows/day; f=0.01 gives 500,000. Multiply measured input/output tokens separately by verified model rates, include retry/thinking tokens and queue latency. No token cost is claimed while the live experiment is unrun. A free tier is an experiment constraint, not a production SLA.',
              '**Protect the CFO dashboard.** Critical schema/date/duplicate failures quarantine affected batches. Semantic suspicion routes to review with lineage and redacted evidence. Use backpressure, tenant budgets and a dead-letter queue; expose freshness and quality status to downstream consumers. LLM failure cannot silently mark a batch healthy. Audit sampled accepted rows to measure blind spots.','',
              'Before production: independently adjudicate real clean/error labels, add corruption diversity and multi-error interactions, rerun on the actual laptop and a large streaming load, measure Gemini and freeze approved model/schema versions.']
    write('RESULTS_B.md',lines)

    lines=['# Decision matrix','', 'Offline choices are provisional. Every number is generated from retained JSON evidence; proxy FPR and missing live measurements remain explicit.','',
           '| Component / check | Classification | Choice and measured justification |','|---|---|---|',
           f"| Tax arithmetic | rule | Handwritten exact agreement {pct(a['measurements'][0]['accuracy'])} with independent oracle; {a['measurements'][0]['differing_inputs']} varying repeated inputs; official checks pending |",
           '| Tax configuration authoring | hybrid | Codex-generated reviewed constants execute as rules; Gemini compilation candidate path unrun; arbitrary legal logic still requires code changes |',
           '| Free-text extraction | hybrid | Conservative rule readiness checks pass 50/50 curated examples; Gemini extraction implemented but unmeasured; explicit clarification required |',
           '| Regime recommendation | rule | Compare computed rounded liabilities; report tie; deterministic in regression checks |',
           '| Legal release | hybrid | Human clause review plus deterministic regression/calculator gate; no automatically promoted generated rules |',
           '| Runtime LLM tax calculation | LLM | Implemented experimental comparator; no offline evidence justifies production use |']
    for p in PROBLEMS:
        family=b['choices'][p]
        x=next(x for x in b['validation'] if x['problem']==p and x['family']==family)
        lines.append(f"| {p} | {family} | Validation recall {pct(x['detection_rate'])}, clean-proxy flags {pct(x['clean_proxy_row_flag_rate'])}; chosen before held-out test; see RESULTS_B for test results |")
    lines += ['| Semantic escalation | hybrid | Capped candidate review plus unflagged sample implemented; LLM evidence pending, cannot claim a measured improvement |',
              '| Every-problem LLM comparator | LLM | All 12 checks implemented in shared reviewer; NOT RUN without Gemini; no invented cost/detection values |']
    write('DECISION_MATRIX.md',lines)
    status={'official_calculator_gate':official['passes_gate'],'gemini_experiments_present':live is not None,
            'full_gemini_tax_suite':bool(live and live.get('full_tax_suite_evaluated')),
            'laptop_throughput_measured':False,'independent_semantic_ground_truth':False,
            'contemporaneous_test_first_history':False,'human_timed_law_migration':False,
            'ready_to_claim_assignment_complete':False}
    write('results/submission_status.json',[json.dumps(status,indent=2)])
    print('Generated RESULTS_A.md, RESULTS_B.md and DECISION_MATRIX.md')


if __name__=='__main__':generate()
